import { ledger } from './service';
http.get('/purchase/ledger', ledger);
graphql.register('Query', 'purchaseSummary', ledger);

import { http } from './transport';
export function fetchLedger() { return http.get('/purchase/ledger'); }
export function fetchSummary() { return http.graphql(`query PurchaseSummary { purchaseSummary { count } }`); }
export function dynamicRequest() { return http.get('/purchase/' + globalThis.target); }

CREATE TABLE purchase_detail (
 tenant_id TEXT, purchase_no TEXT, line_no INTEGER, supplier_id TEXT,
 ordered_qty INTEGER, unit_price_cents INTEGER, status TEXT,
 PRIMARY KEY(tenant_id, purchase_no, line_no));
CREATE TABLE supplier (tenant_id TEXT, supplier_id TEXT, name TEXT, PRIMARY KEY(tenant_id,supplier_id));
CREATE TABLE receipt (id TEXT PRIMARY KEY, tenant_id TEXT, purchase_no TEXT, line_no INTEGER, qty INTEGER, status TEXT, deleted INTEGER,
 FOREIGN KEY(tenant_id,purchase_no,line_no) REFERENCES purchase_detail(tenant_id,purchase_no,line_no));
CREATE TABLE return_line (id TEXT PRIMARY KEY, tenant_id TEXT, purchase_no TEXT, line_no INTEGER, qty INTEGER, status TEXT, deleted INTEGER,
 FOREIGN KEY(tenant_id,purchase_no,line_no) REFERENCES purchase_detail(tenant_id,purchase_no,line_no));
CREATE TABLE invoice (id TEXT PRIMARY KEY, tenant_id TEXT, purchase_no TEXT, line_no INTEGER, amount_cents INTEGER, status TEXT, deleted INTEGER,
 FOREIGN KEY(tenant_id,purchase_no,line_no) REFERENCES purchase_detail(tenant_id,purchase_no,line_no));

export function ledger() { return erp.query(ledgerSql); }
export const ledgerSql = `SELECT * FROM purchase_detail WHERE tenant_id = :tenant`;
export const dynamicSql = 'SELECT * FROM ' + runtimeTable;

export const erp = orm.connect('ds.erp');
export const analytics = orm.connect('ds.analytics');
export const Purchase = erp.model('purchase_detail', ['tenant_id', 'purchase_no', 'line_no']);
export const OtherPurchase = analytics.model('purchase_detail', ['tenant_id', 'purchase_no', 'line_no']);

import Ledger from './pages/Ledger';
export const router = { id: 'main', mode: 'hash' };
export const routes = [{ path: '/Other/purchaseLedger', alias: '/purchase', titleKey: 'purchase.title', component: Ledger }];

import { fetchLedger, fetchSummary, dynamicRequest } from '../requests';
/** 采购台账：供应商筛选。 */
export function Ledger() {
  async function query() { return fetchLedger(); }
  async function summary() { return fetchSummary(); }
  return <section><button onClick={query}>查询</button><button onClick={summary}>汇总</button><button onClick={dynamicRequest}>动态查询</button></section>;
}
export default Ledger;

CREATE TABLE purchase_detail (
 tenant_id TEXT, purchase_no TEXT, line_no INTEGER, supplier_id TEXT,
 ordered_qty INTEGER, unit_price_cents INTEGER, status TEXT,
 PRIMARY KEY(tenant_id, purchase_no, line_no));
CREATE TABLE supplier (tenant_id TEXT, supplier_id TEXT, name TEXT, PRIMARY KEY(tenant_id,supplier_id));
CREATE TABLE receipt (id TEXT PRIMARY KEY, tenant_id TEXT, purchase_no TEXT, line_no INTEGER, qty INTEGER, status TEXT, deleted INTEGER,
 FOREIGN KEY(tenant_id,purchase_no,line_no) REFERENCES purchase_detail(tenant_id,purchase_no,line_no));
CREATE TABLE return_line (id TEXT PRIMARY KEY, tenant_id TEXT, purchase_no TEXT, line_no INTEGER, qty INTEGER, status TEXT, deleted INTEGER,
 FOREIGN KEY(tenant_id,purchase_no,line_no) REFERENCES purchase_detail(tenant_id,purchase_no,line_no));
CREATE TABLE invoice (id TEXT PRIMARY KEY, tenant_id TEXT, purchase_no TEXT, line_no INTEGER, amount_cents INTEGER, status TEXT, deleted INTEGER,
 FOREIGN KEY(tenant_id,purchase_no,line_no) REFERENCES purchase_detail(tenant_id,purchase_no,line_no));

import { query } from './workers';
export const moduleInfo = { key: 'purchase', name: '采购模块' };
scheduler.register('nightly-ledger', query);
messages.subscribe('purchase.refresh', query);
commands.register('refresh-ledger', query);

import { erp, analytics, Purchase } from './models';
// 原文包含中文与转义；证据引用完整字符串，不假造 SQL token 偏移。
export function boundLedger() {
  return erp.query("SELECT tenant_id, purchase_no, line_no FROM purchase_detail WHERE status = 'APPROVED'\n");
}
export function wrongInstance() { return analytics.query('SELECT tenant_id FROM purchase_detail'); }
export function modelRows() { return Purchase.findAll(); }
export function dynamicQuery(table) { return erp.query('SELECT * FROM ' + table); }
export function shadowed(erp) { return erp.query('SELECT * FROM purchase_detail'); }
export function shadowedLocal() { const erp = runtimeDb; return erp.query('SELECT * FROM purchase_detail'); }
export function unsupportedOrm() { return erp.raw('SELECT * FROM purchase_detail'); }
